--
-- Table structure for table `scanner_app_lot`
--

DROP TABLE IF EXISTS `scanner_app_lot`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `scanner_app_lot` (
  `lot_id` int NOT NULL,
  `title` varchar(1023) NOT NULL,
  `description` longtext,
  `base_price` decimal(15,2) NOT NULL,
  `start_date` datetime(6) DEFAULT NULL,
  `end_date` datetime(6) DEFAULT NULL,
  `announcement_date` datetime(6) DEFAULT NULL,
  `court_name` varchar(1023) DEFAULT NULL,
  `trade_type` varchar(255) DEFAULT NULL,
  `is_favorite` tinyint(1) NOT NULL,
  `app_status` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `category_id` bigint DEFAULT NULL,
  `city_id` bigint DEFAULT NULL,
  `district_id` bigint DEFAULT NULL,
  `region_id` bigint DEFAULT NULL,
  `status_id` bigint DEFAULT NULL,
  PRIMARY KEY (`lot_id`),
  KEY `scanner_app_lot_category_id_b83d27aa_fk_scanner_app_category_id` (`category_id`),
  KEY `scanner_app_lot_city_id_50288f0b_fk_scanner_app_city_id` (`city_id`),
  KEY `scanner_app_lot_district_id_aaba810c_fk_scanner_app_district_id` (`district_id`),
  KEY `scanner_app_lot_region_id_464a5e91_fk_scanner_app_region_id` (`region_id`),
  KEY `scanner_app_lot_status_id_8b375efc_fk_scanner_app_status_id` (`status_id`),
  CONSTRAINT `scanner_app_lot_category_id_b83d27aa_fk_scanner_app_category_id` FOREIGN KEY (`category_id`) REFERENCES `scanner_app_category` (`id`),
  CONSTRAINT `scanner_app_lot_city_id_50288f0b_fk_scanner_app_city_id` FOREIGN KEY (`city_id`) REFERENCES `scanner_app_city` (`id`),
  CONSTRAINT `scanner_app_lot_district_id_aaba810c_fk_scanner_app_district_id` FOREIGN KEY (`district_id`) REFERENCES `scanner_app_district` (`id`),
  CONSTRAINT `scanner_app_lot_region_id_464a5e91_fk_scanner_app_region_id` FOREIGN KEY (`region_id`) REFERENCES `scanner_app_region` (`id`),
  CONSTRAINT `scanner_app_lot_status_id_8b375efc_fk_scanner_app_status_id` FOREIGN KEY (`status_id`) REFERENCES `scanner_app_status` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

